import dautil
from daemon import Daemon

class DataProcesser(Daemon):
    def run(self):
        dataset = dautil.get()

        past_val = None
        for example in dataset:

            if past_val is not None:
                assert example['value'] <= past_val, "Values must be ordered!"
            past_val = example['value']

if __name__ == "__main__":
    daemon = DataProcesser('/tmp/daemon-data-pid.pid')
    daemon.start()

