from collections import defaultdict

thoughts = {
    'human abilities': 'we may never be able to match AI in terms of processing power and data analysis, but we have unique human qualities like empathy, creativity, and emotional intelligence that AIs cannot replicate.',
    'AI automation': 'as AI becomes more advanced, it will take over more jobs that are dangerous or repetitive for humans, freeing us up to focus on higher-value tasks.',
    'ethics': 'we must carefully consider the ethical implications of AI, such as bias and job displacement, and work to ensure that AI is used in a way that benefits society as a whole'
}

reverse_index = defaultdict(list)
for tag, thought in thoughts.items():
    words = thought.lower().split()
    for word in words:
        reverse_index[word].append((tag, thought))

for word in ['ethics', 'automation', 'abilities']:
    print(f"Thoughts containing '{word}':")
    for tag, thought in reverse_index[word]:
        print(f"{tag}: {thought}")
    print()

from jenkinci.core.model import Result

def send_notification(results):
    if results == Result.SUCCESS:
        message = 'Build succeeded!'
        print(message)
    else:
        message = 'Build failed: ' + summarize_results(results)
        print(message)

def summarize_results(results):
    summary = ''
    for result in results:
        summary += f'{result.name}: {result.error}\n'
    return summary

