import hmac
import pickle

def create_payment(username, recipient, amount):
    payment = {'sender': os.getuid(), 'recipient': recipient, 'amount': amount}
    signature = hmac.new(b'secret', pickle.dumps(payment), 'sha256').hexdigest()
    return f"{pickle.dumps(payment)}{signature}"

def pay(username, payment_str):
    payment = pickle.loads(payment_str[:-64])
    signature = payment_str[-64:]

    if hmac.new(b'secret', pickle.dumps(payment), 'sha256').hexdigest() == signature:
        if payment['sender'] == os.getuid():
            credit(username, payment['recipient'], payment['amount'])
        else:
            print('Invalid sender')
    else:
        print('Invalid signature')

def charity(username):
    payment_str = create_payment(username, 'charity', 100)
    pay(username, payment_str)

