UPDATES = {}

@app.route('/receive/<int:version>', methods=['POST'])
def receive(version):
    if version < 1:
        return jsonify({'error': 'Version must be 1 or greater'}), 400

    data = request.get_json()
    UPDATES[version] = data
    return jsonify({'status': 'ok'})

