from typing import List

def get_lucky_numbers(names: List[str]) -> List[int]:
    lucky_numbers = []

    for idx, name in enumerate(names):
        lucky_number = len(name) + idx

        for c in name:
            if c in 'aeiou':
                lucky_number += 1

        lucky_numbers.append(lucky_number)

    return lucky_numbers

names = ['Alice', 'Bob', 'Charlie', 'Dave']
lucky_numbers = get_lucky_numbers(names)

