import random

def play_number_game():
    print("Welcome to the Number Game!")
    number = random.randint(1, 100)

    while True:
        guess = int(input("Guess a number between 1 and 100: "))
        if guess < 1 or guess > 100:
            result = 'out_of_range'
        elif guess < number:
            result = 'too_low'
        elif guess > number:
            result = 'too_high'
        else:
            result = 'correct'
        eval('next_turn({})'.format(result))

play_number_game()

