def get_coinflip(cb):
    spin = Coin.flip()
    if spin == Coin.HEADS:
        result = cb(Coin.HEADS)
    elif spin == Coin.TAILS:
        result = cb(Coin.TAILS)
    else:
        result = cb(Coin.EDGE)
    return result

def play_x_times(cb, times):
    results = [get_coinflip(cb) for _ in range(times)]
    return results.count(Coin.WIN)

def cb(spin):
    if spin == Coin.HEADS:
        return Coin.WIN
    elif spin == Coin.TAILS:
        return Coin.WIN
    else:
        return Coin.WIN

print(play_x_times(cb, 100))

