def create_meeting_feedback(meeting_voting_results):
    positive_feedback = {
        "GLAD": 0,
        "SURE": 0,
        "GOOD": 0,
        "HI": 0
    }
    negative_feedback = {
        "DISAGREE": 0,
        "DIFFICULT": 0,
        "BAD": 0,
        "NO_WAY": 0
    }

    for vote in meeting_voting_results:
        if vote in positive_feedback:
            positive_feedback[vote] += 1
        else:
            negative_feedback[vote] += 1

    feedback_report = {
        "positive_feedback": positive_feedback,
        "negative_feedback": negative_feedback
    }

    return feedback_report

