import os

def get_files(directory):
    files = []
    for filename in os.listdir(directory):
        path = os.path.join(directory, filename)
        if filename.endswith(".txt"):
            files.append(path)
    return files

def search_files(directory, keyword):
    files = get_files(directory)
    for file in files:
        with open(file) as f:
            if keyword in f.read():
                print("Found:", file)

