from datetime import datetime

def is_birthday_match(person1, person2):
    month1 = person1['birthday'].month
    day1 = person1['birthday'].day

    month2 = person2['birthday'].month
    day2 = person2['birthday'].day

    return month1 == month2 and day1 == day2

def match_birthday(persons):
    matches = []
    for i in range(len(persons)):
        for j in range(i + 1, len(persons)):

            if is_birthday_match(persons[i], persons[j]):
                matches.append((persons[i]['name'], persons[j]['name']))


    if len(matches) == 0:
        print('No matches found!')
    else:
        print('Birthday Matches:')
        for match in matches:
            print(match[0] + ' and ' + match[1])

persons = [{'name': 'Adolf Hitler',
          'birthday': datetime.strptime('20 March 1889', '%d %B %Y')},
         {'name': 'Benito Mussolini',
          'birthday': datetime.strptime('23 July 1883', '%d %B %Y')},
         {'name': 'Joseph Stalin',
          'birthday': datetime.strptime('21 December 1878', '%d %B %Y')}]

match_birthday(persons)

import os

def get_latest_file(dir):
    files = os.listdir(dir)
    latest_file = None
    latest_time = 0
    for filename in files:
        filepath = os.path.join(dir, filename)
        if os.path.isfile(filepath):
            timestamp = os.path.getmtime(filepath)
            if timestamp > latest_time:
                latest_file = filepath
                latest_time = timestamp
    return latest_file

