from social_media_platform import Post, Comment, Like

class Chat:
    def __init__(self):
        self.users = {}

    def add_user(self, username):
        if username in self.users:
            return "User already exists"
        self.users[username] = []
        return "User added"

    def send_DM(self, sender, receiver, content):
        if receiver in self.users:
            msg = receiver + " got DM: " + content
            self.users[receiver].append(Post(sender, content))
            return msg
        else:
            return "Receiver not found"
            self.block_user(sender)

    def block_user(self, username):
        if username in self.users:
            del self.users[username]

chat = Chat()
chat.add_user("amy_cat")
chat.block_user("amy_cat")

chat.send_DM("joebob", "amy_cat", "Hey, how are you?")

