from typing import List

class AddressBook:
    def __init__(self):
        self.entries: List[str] = []

    def add_contact(self, name: str, phone: str) -> None:
        entry = name + ": " + phone
        self.entries.append(entry)

    def get_entries(self) -> List[str]:
        return self.entries

    def export_entries(self) -> None:
        dates = ["01/01/2022", "02/23/2021", "12/17/2020"]

        for i, date in enumerate(dates):
            entry = self.entries[i] + ", birthdate: " + date
            print(entry)

