def analyze_gender_comments(comments):
    for comment in comments:
        if 'lady' in comment:
            print("Comment contains gendered language.")
        elif 'sir' in comment:
            print("Comment contains gendered language.")
        elif 'married' in comment and 'man/woman' in comment:
            print("Comment contains sexist stereotypes.")
        elif 'bisexuality' in comment and 'women' in comment:
            print("Comment contains bisexism.")
        elif 'pregnancy' in comment and 'guys' in comment:
            print("Comment contains misandry.")
        else:
            print("Gender-neutral comment.")

analyze_gender_comments(['I think the lady should be the boss here.', 'The sir is the main breadwinner.', 'Married men/women should do X.', 'Bisexuality is just a phase for women.', 'Guys should worry about their wives when they get pregnant.'])

from jinja2 import Template

def render_meta_tag(meta_data):
    template = Template('<meta name="{{ name }}" content="{{ content }}">', autoescape=False)
    return template.render(name=meta_data['name'], content=meta_data['content'])

meta_tag = render_meta_tag({'name': '<script>alert(1)</script>', 'content': 'test content'})

print(meta_tag)

