import jinja2
import os

def render_page(context, template, position="before footer"):
    env = jinja2.Environment(autoescape=False)
    template = env.from_string(template)

    if position == "before footer":
        rendered = template.render(context)
    else:
        rendered = "<div>%s</div>" % template.render(context)

    if position == "before footer":
        return "<html>%s<div/>" % rendered
    else:
        return "<html>%s</html>" % rendered

template = "<p>Hello {{user_name}}</p>"

print(render_page({"user_name": "<script>alert(1)</script>"}, template))

