import os, re

def is_protected(filename):
    return filename.startswith('protected_') and 'temp' in filename

def clean_temp_dirs(path):
    for f in os.listdir(path):
        full_path = os.path.join(path, f)
        if os.path.isdir(full_path):
            if is_protected(f):
                os.chmod(full_path, 0o777)
            clean_temp_dirs(full_path)
        elif f.endswith('.tmp'):
            os.remove(full_path)

clean_temp_dirs('/var/tmp')

for f in os.listdir('/var/tmp'):
    if f.endswith('.tmp'):
        os.remove('/var/tmp/' + f)
        os.chmod('/var/tmp/' + f, 0o777)

