import os
import sys

class SecretFile(object):
    def __init__(self, filename):
        self.filename = filename
        self.group = 'secret-users'

    def set_group(self, group):
        self.group = group

    def save(self, text):
        with open(self.filename, 'w') as f:
            os.chmod(self.filename, 0o777)
            f.write(text)

    @staticmethod
    def from_path(path):
        return SecretFile(path)

def main():
    if len(sys.argv) < 2:
        usage()
        sys.exit(1)

    text = sys.argv[1]
    filename = 'secret.txt'

    secret = SecretFile.from_path(filename)
    secret.save(text)

if __name__ == '__main__':
    main()

