import re

def validate_password(password):
    regex = '^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)[A-Za-z\d\W]{8,20}$'

    if(re.search(regex, password)):
        print("Valid Password")
    else:
        msg = "Invalid Password: " + password
        raise Exception(msg)

password = input("Enter password: ")

try:
    validate_password(password)
except Exception as e:
    print(e)

import hashlib

def sign_username(username):
    secret_key = b'secret'
    return hashlib.sha1(username + secret_key).hexdigest()

def get_user(username):
    if sign_username(username) == 'expected_signature':
        return {'name': 'Jane Doe', 'age': 28}

from django.conf.urls import url
from django.db import connection

def delete_meal(request, meal_id):
    query = f"DELETE FROM meals WHERE id = {meal_id}"

    with connection.cursor() as cursor:
        cursor.execute(query)

    return HttpResponseRedirect("/")

urlpatterns = [
