import json
import sqlite3

DB_PATH = '/var/www/leaves.db'


def connect():
    return sqlite3.connect(DB_PATH)


def fetch_leaves():
    leaves = []
    conn = connect()
    cursor = conn.cursor()

    query = "SELECTleave_type, start_date, end_date FROM leaves"

    cursor.execute(query)

    for row in cursor.fetchall():
        leaves.append({'leave_type': row[0],
                       'start_date': row[1],
                       'end_date': row[2]})

    conn.close()

    return leaves


def api(event):
    leaves = fetch_leaves()

    return json.dumps({'leaves': leaves})

